    ]

    /// One puzzle for a difficulty, deterministically picked with a seed.
    static func puzzle<G: RandomNumberGenerator>(for difficulty: Difficulty, seen: Set<Int> = [], using generator: inout G) -> (
        puzzle: SlidingBlocksPuzzle, index: Int
    )? {
        let level = difficulty.level
        guard level >= 1 && level <= puzzlesPerLevel.count else { return nil }
        let pool = puzzlesPerLevel[level - 1]
        let unseen = pool.indices.filter { !seen.contains($0) }
        let pickFrom = unseen.isEmpty ? Array(pool.indices) : unseen
        guard !pickFrom.isEmpty else { return nil }
        let chosen = pickFrom[Int.random(in: pickFrom.indices, using: &generator)]
        return (pool[chosen], chosen)
    }
}
